const {chromium}=require('playwright'),fs=require('fs'),os=require('os'),path=require('path'),http=require('http'),assert=require('assert/strict'),{execFileSync}=require('child_process');
const repo=path.resolve(__dirname,'../..'),dir=fs.mkdtempSync(path.join(os.tmpdir(),'sambaadm-search-'));
execFileSync('go',['test','./internal/web','-run','^TestWorkspaceBrowserFixtures$','-count=1'],{cwd:repo,env:{...process.env,SAMBAADM_WEB_FIXTURE_DIR:dir}});
const server=http.createServer((req,res)=>{const p=new URL(req.url,'http://localhost').pathname,file=p.startsWith('/static/')?path.join(repo,'internal/web',p):path.join(dir,'admin-'+p.slice(1)+'.html');if(!fs.existsSync(file)){res.writeHead(404).end();return;}res.setHeader('Content-Type',file.endsWith('.js')?'application/javascript':file.endsWith('.css')?'text/css':'text/html');res.end(fs.readFileSync(file));});
(async()=>{await new Promise(r=>server.listen(0,'127.0.0.1',r));const browser=await chromium.launch({headless:true});try{const page=await browser.newPage();const errors=[];page.on('pageerror',e=>errors.push(e.message));let uploads=0,fail=false,photo=false;await page.route('**/api/v1/**',async route=>{const req=route.request(),p=new URL(req.url()).pathname;let result={samAccountName:'anna',displayName:'Анна Иванова',revision:String(uploads),photo,groups:[]};if(p.endsWith('/photo')&&req.method()==='POST'){uploads++;assert.ok(req.headers()['x-csrf-token']);assert(req.postDataBuffer().length<100000,'phone photo must resize before upload');if(fail){await route.fulfill({status:409,json:{error:'Профиль изменился. Обновите страницу.'}});return;}photo=!req.postDataBuffer().toString().includes('name="remove"');result.photo=photo;result.revision=String(uploads);}if(p.endsWith('/photo')&&req.method()==='GET'){await route.fulfill({status:200,contentType:'image/png',body:Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+a9WQAAAAASUVORK5CYII=','base64')});return;}await route.fulfill({json:result});});await page.goto('http://127.0.0.1:'+server.address().port+'/me');await page.getByRole('button',{name:'Изменить фотографию',exact:true}).waitFor();assert.equal(await page.getByRole('heading',{name:'Фотография',exact:true}).count(),0);await page.getByLabel('Телефон',{exact:true}).fill('123456');const chooserPromise=page.waitForEvent('filechooser');await page.getByRole('button',{name:'Изменить фотографию',exact:true}).click();const chooser=await chooserPromise;const jpeg=await page.evaluate(async()=>{const c=document.createElement('canvas');c.width=4032;c.height=3024;const ctx=c.getContext('2d');ctx.fillStyle='#0f766e';ctx.fillRect(0,0,c.width,c.height);return c.toDataURL('image/jpeg').split(',')[1];});await chooser.setFiles({name:'phone.jpg',mimeType:'image/jpeg',buffer:Buffer.from(jpeg,'base64')});await page.getByText('Фотография обновлена',{exact:true}).waitFor();assert.equal(uploads,1);assert.equal(await page.getByLabel('Телефон',{exact:true}).inputValue(),'123456','unsaved contacts preserved');await page.getByRole('img',{name:'Моя фотография',exact:true}).waitFor();await page.getByRole('button',{name:'Удалить фото',exact:true}).click();await page.getByRole('button',{name:'Удалить фото',exact:true}).waitFor({state:'detached'});fail=true;await page.getByLabel('Выбрать фотографию',{exact:true}).setInputFiles({name:'phone.jpg',mimeType:'image/jpeg',buffer:Buffer.from(jpeg,'base64')});await page.getByText('Профиль изменился. Обновите страницу.',{exact:true}).waitFor();assert.equal(await page.getByRole('button',{name:'Изменить фотографию',exact:true}).isEnabled(),true);assert.deepEqual(errors,[]);console.log('PASS avatar file picker, automatic phone-image resize/upload, CSRF, image refresh, delete, conflict and preserved contact drafts');}finally{await browser.close();server.close();}})().catch(e=>{console.error(e);server.close();process.exitCode=1;});
